CREATE OR REPLACE FUNCTION public.icash_claim_owner_before_recovery_cap(p_account uuid, p_screening uuid, p_operation text, p_snapshot jsonb, p_rate uuid, p_credit_cap integer, p_unit_cost_micros bigint, p_quoted_data_cost_micros bigint, p_rights_until timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
 o public.icash_operation_spend;
 s public.icash_screening_jobs;
 c public.icash_discovery_configs;
 r public.icash_operation_rates;
 prop text;manual_hold boolean;fetched timestamptz;checked_at timestamptz;
begin
 if p_account is null or p_screening is null or p_operation is distinct from 'owners:'||p_account||':'||p_screening
  or jsonb_typeof(p_snapshot) is distinct from 'object' or p_rate is null
  or p_credit_cap is null or p_credit_cap not between 1 and 25
  or p_unit_cost_micros is null or p_unit_cost_micros not between 1 and 9007199254740991
  or p_quoted_data_cost_micros is null or p_quoted_data_cost_micros not between 1 and 9007199254740991
  or p_credit_cap::numeric*p_unit_cost_micros>p_quoted_data_cost_micros or p_rights_until is null then return false;end if;
 -- Match the underlying claim's budget -> operation -> account order. Existing
 -- takeover paths lock the account (and current wrappers lock budget first).
 perform 1 from public.icash_operating_budget where id=1 for update;
 if not found then return false;end if;
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.account_id is distinct from p_account or o.rate_id is distinct from p_rate or o.state<>'reserved' or o.permission_until is distinct from p_rights_until then return false;end if;
 perform 1 from public.icash_accounts where id=p_account and not bot_paused for update;
 if not found then return false;end if;
 select * into s from public.icash_screening_jobs where id=p_screening and account_id=p_account for share;
 if not found or s.state<>'complete' or s.snapshot ? 'sellerRequest' or s.snapshot is distinct from p_snapshot or s.result->'financialCheck'->>'status' is distinct from 'eligible' then return false;end if;
 prop:=s.snapshot->>'propertyId';
 if prop is null or prop !~ '^prop_[0-9]{1,20}$' or s.snapshot->'raw'->'data'->>'dm_property_id' is distinct from prop or s.snapshot->>'propertyType' is distinct from 'house' then return false;end if;
 -- Inventory rotation can already hold config before its scheduler takes budget.
 -- Fail closed instead of waiting for that row while this claim holds budget.
 begin
  select * into c from public.icash_discovery_configs where account_id=p_account for share nowait;
 exception when lock_not_available then return false;end;
 if not found or not c.enabled or not c.contacts_enabled or c.contact_rate_id is distinct from p_rate
  or c.contact_credit_cap is distinct from p_credit_cap or c.property_credit_micros is distinct from p_unit_cost_micros
  or c.data_rights_until is distinct from p_rights_until then return false;end if;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 if not found or not r.enabled or r.operation<>'owner_enrichment'
  or jsonb_typeof(r.costs_micros->'dealmachine') is distinct from 'number'
  or (r.costs_micros->>'dealmachine')::numeric is distinct from p_quoted_data_cost_micros::numeric then return false;end if;
 -- A locked row must exist even for a property's first lookup. Do not change an
 -- existing manual choice. This also serializes direct property-control upserts.
 insert into public.icash_property_controls(account_id,property_id,manual) values(p_account,prop,false) on conflict do nothing;
 select manual into manual_hold from public.icash_property_controls where account_id=p_account and property_id=prop for update;
 if not found or manual_hold then return false;end if;
 begin fetched:=(s.snapshot->>'fetchedAt')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then return false;end;
 -- Use wall clock after waiting for all locks, rather than transaction-start time.
 checked_at:=clock_timestamp();
 if fetched is null or fetched<checked_at-interval '24 hours' or fetched>checked_at
  or s.completed_at is null or s.completed_at<checked_at-interval '24 hours' or s.completed_at>checked_at
  or c.data_rights_until<=checked_at or r.expires_at<=checked_at or r.verified_at>checked_at
  or o.permission_until<=checked_at then return false;end if;
 -- No weakened or copied billing implementation: activation, pause, funds, rate,
 -- reservation state and exactly-once checks remain in the existing dispatcher.
 if not public.icash_research_purchase_allowed(p_account,p_operation,p_rate) then return false;end if; return public.icash_claim_operation(p_operation);
end $function$

CREATE OR REPLACE FUNCTION public.icash_next_acquisition()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;j uuid;t public.icash_automation_tickets;backlog integer;allowance bigint;minimum_quote bigint;
begin
 perform 1 from public.icash_operating_budget where id=1 and enabled for update;
 if not found then return null;end if;
 perform public.icash_settle_pending_dealmachine();
 -- Expiry/exhaustion is terminal only for this exact proven-unstarted family.
 update public.icash_automation_tickets retry_ticket set outcome=case when owner_preview_deferrals>=8 then 'owner_preview_retry_exhausted' else 'owner_preview_expired' end
 where retry_ticket.kind='contacts' and retry_ticket.state='held' and retry_ticket.outcome='owner_preview_rate_limited'
 and (retry_ticket.owner_preview_deferrals>=8 or retry_ticket.owner_preview_retry_until<=clock_timestamp())
 and public.icash_owner_enrichment_unstarted(retry_ticket.account_id,retry_ticket.screening_id,'owners:'||retry_ticket.account_id||':'||retry_ticket.screening_id);
 update public.icash_automation_tickets set state='held',outcome='expired' where kind in ('contacts','discovery') and state='issued' and expires_at<=now();
 -- Leave other scheduler work available; billing and expiry checks above still run.
 if not public.icash_dealmachine_capacity_available() then return null;end if;
 for c in select d.* from public.icash_discovery_configs d join public.icash_accounts a on a.id=d.account_id join public.icash_wallets w on w.account_id=a.id
 where d.enabled and d.auto_enabled and d.next_run_at<=now() and d.data_rights_until>now() and not a.bot_paused and w.balance_cents>w.reserved_cents
 and not exists(select 1 from public.icash_automation_tickets x where x.account_id=a.id and ((x.state='issued' and x.expires_at>now()) or (x.state='consumed' and x.created_at>now()-interval '5 minutes')))
 order by
  (d.next_run_at<now()-interval '5 minutes') desc,
  case when d.next_run_at<now()-interval '5 minutes' then d.next_run_at end,
  coalesce((public.icash_daily_work_target(d.account_id)->>'priorityRatio')::numeric,1),
  d.next_run_at,d.account_id limit 5 for update of d skip locked loop
 perform public.icash_refresh_opportunity_outcomes(c.account_id);
 allowance:=public.icash_prospecting_available(c.account_id);
 select min(quote) into minimum_quote from (
  select public.icash_research_admission_quote(c.account_id,'property_search',r.charge_cents) quote
   from public.icash_operation_rates r where r.id=c.rate_id
  union all
  select public.icash_research_admission_quote(c.account_id,'owner_enrichment',r.charge_cents)
   from public.icash_operation_rates r where c.contacts_enabled and r.id=c.contact_rate_id
 ) quotes;
 if minimum_quote is null or allowance<minimum_quote then
  update public.icash_discovery_configs set next_run_at=now()+interval '60 seconds' where account_id=c.account_id;
  continue;
 end if;
 j:=null;
 if c.contacts_enabled and c.contact_rate_id is not null then j:=public.icash_enrichment_candidate(c.account_id);end if;
 if j is not null then
 update public.icash_discovery_configs set next_run_at=now()+interval '5 seconds' where account_id=c.account_id;
 insert into public.icash_automation_tickets(account_id,kind,screening_id) values(c.account_id,'contacts',j)
 on conflict(screening_id) do update set token=gen_random_uuid()::text||gen_random_uuid()::text,state='issued',outcome=null,completed_at=null,created_at=now(),expires_at=least(now()+interval '2 minutes',coalesce(public.icash_automation_tickets.owner_preview_retry_until,now()+interval '2 minutes')),issue_attempts=case when public.icash_automation_tickets.outcome='owner_preview_rate_limited' then public.icash_automation_tickets.issue_attempts else public.icash_automation_tickets.issue_attempts+1 end
 returning * into t;
 return jsonb_build_object('token',t.token);
 end if;
 -- Provider capacity remains bounded while completed attempts free the queue.
 backlog:=public.icash_pending_opportunity_count(c.account_id);
 update public.icash_discovery_configs set next_run_at=now()+case when allowance>0 then interval '5 seconds' else interval '60 seconds' end where account_id=c.account_id;
 if c.exhausted or backlog>=c.max_open_prospects or not public.icash_outbound_search_due(c.account_id) then continue;end if;
 insert into public.icash_automation_tickets(account_id,kind) values(c.account_id,'discovery') returning * into t;
 return jsonb_build_object('token',t.token);
 end loop;
 return null;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_discovery_inventory(p_account uuid, p_revision uuid, p_page integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;cur record;cached jsonb;n integer:=0;streak integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or not c.enabled or not c.auto_enabled or c.data_rights_until<=now()
 or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
 or not public.icash_membership_work_allowed(p_account) then return 'inventory_held';end if;
 if exists(select 1 from public.icash_operation_spend where operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and state<>'reserved') then return 'awaiting_reconciliation';end if;
 perform public.icash_expand_inventory_markets(p_account);
 select count(*) into streak from (select queued_properties,returned_properties,duplicate_properties from public.icash_discovery_inventory_receipts where account_id=p_account and revision=p_revision order by created_at desc limit 3) recent
 where queued_properties=0 and returned_properties=duplicate_properties;
 if streak=3 then
  update public.icash_inventory_markets set next_scan_at=greatest(next_scan_at,now()+interval '6 hours') where account_id=p_account and zip=c.zip;
  update public.icash_discovery_configs set exhausted=true where account_id=p_account;
  if public.icash_rotate_inventory_market(p_account) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return 'ready';end if;
 perform public.icash_discovery_filter_state_v2(p_account,p_revision,p_page);
 for cur in select * from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted order by strategy for update loop
  loop
   cached:=public.icash_known_assigned_discovery_page(c.zip,cur.strategy,cur.next_page,c.per_page);
   exit when cached is null;
   update public.icash_discovery_filter_cursors set next_page=next_page+1,skipped_assigned_pages=skipped_assigned_pages+1,exhausted=not (cached->>'hasNextPage')::boolean
   where account_id=p_account and revision=p_revision and strategy=cur.strategy;
   cur.next_page:=cur.next_page+1;n:=n+1;
   if n>=64 then return 'inventory_advancing';end if;
   exit when not (cached->>'hasNextPage')::boolean;
  end loop;
 end loop;
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
  if exists(select 1 from public.icash_discovery_configs where account_id=p_account and revision<>p_revision) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 return 'ready';
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_filtered_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text, p_plan jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op text:='discovery:'||p_account||':'||p_revision||':'||p_page;
begin
 if not public.icash_discovery_filter_plan_valid(p_plan) then return false;end if;
 -- The original admission function retains every budget, permission and scope gate.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled)
 or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op) then return false;end if;
 perform 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and zip=p_zip
 and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted for update;
 if not found then return false;end if;
 if public.icash_known_assigned_discovery_page(p_zip,p_plan->>'strategy',(p_plan->>'providerPage')::integer,p_per_page) is not null
 or exists(select 1 from public.icash_discovery_filter_pages fp join public.icash_operation_spend os using(operation_key,account_id)
 join public.icash_discovery_configs dc on dc.account_id=fp.account_id where fp.zip=p_zip and fp.plan->>'strategy'=p_plan->>'strategy'
 and fp.plan->>'providerPage'=p_plan->>'providerPage' and dc.per_page=p_per_page and fp.state='claimed' and os.state not in ('settled','cancelled')) then return false;end if;
 if not public.icash_reserve_and_claim_property_discovery(p_account,p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until,p_setup_revision,p_market_mode,p_market) then return false;end if;
 insert into public.icash_discovery_filter_pages(operation_key,account_id,revision,sequence,zip,plan,state) values(op,p_account,p_revision,p_page,p_zip,p_plan,'claimed');
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_property_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;s public.icash_bot_setups;g public.icash_property_zip_geographies;
 r public.icash_operation_rates;o public.icash_operation_spend;known_shortlist boolean:=false;op text;checked timestamptz;
begin
 -- Keep the existing global financial lock order before narrower account/config locks.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 if not found then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found then return false;end if;
 select * into s from public.icash_bot_setups where account_id=p_account for share;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 perform 1 from public.icash_market_shortlist where zip=p_zip and state ~ '^[A-Z]{2}$' for share;
 known_shortlist:=found;
 if not known_shortlist then select * into g from public.icash_property_zip_geographies where zip=p_zip for share;end if;
 checked:=clock_timestamp();
 if not c.enabled or not c.auto_enabled or c.exhausted or c.data_rights_until<=checked
 or row(c.zip,c.revision,c.next_page,c.per_page,c.rate_id,c.property_credit_micros,c.data_rights_until)
 is distinct from row(p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until)
 or row(s.revision,s.profile->>'marketMode',s.profile->>'market') is distinct from row(p_setup_revision,p_market_mode,p_market)
 or (s.profile->>'marketMode'='city' and trim(s.profile->>'market') ~ '^[0-9]{5}$' and trim(s.profile->>'market')<>p_zip)
 or r.operation is distinct from 'property_search' or not coalesce(r.enabled,false) or r.expires_at<=checked
 or p_page<1 or p_per_page not between 1 and 10 or p_unit<1
 or (not known_shortlist and (g.state_code is null or g.property_count is null or g.property_count<=0 or g.checked_at is null or g.checked_at>checked or g.expires_at is null or g.expires_at<=checked)) then return false;end if;
 if not public.icash_research_zip_known(p_zip) or not public.icash_outbound_search_due(p_account) then return false;end if;
 op:='discovery:'||p_account||':'||p_revision||':'||p_page;
 select * into o from public.icash_operation_spend where operation_key=op for update;
 if found and (o.state<>'reserved' or row(o.account_id,o.rate_id,o.permission_until) is distinct from row(p_account,p_rate,p_permission_until)) then return false;end if;
 perform public.icash_reserve_operation(p_account,op,p_rate,p_permission_until,null,false);
 -- now() is the transaction start, so use wall-clock time again after any downstream wait.
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired before claim';
 end if;
 if not public.icash_claim_operation(op) then raise exception 'Property discovery claim held';end if;
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired during claim';
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_save_contacts(p_account uuid, p_screening uuid, p_operation text, p_result jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare o public.icash_operation_spend; prior jsonb; used bigint;
begin
 select * into o from public.icash_operation_spend where operation_key=p_operation for update;
 if not found or o.account_id<>p_account or o.state<>'dispatched' then raise exception 'Dispatched enrichment required';end if;
 if not exists(select 1 from public.icash_screening_jobs where id=p_screening and account_id=p_account and state='complete') then raise exception 'Tenant screening required';end if;
 select result into prior from public.icash_owner_contacts where screening_id=p_screening;
 if found then if prior<>p_result then raise exception 'Contact result conflict';end if;return;end if;
 used:=(p_result->>'creditsUsed')::bigint;
 if used is null or used<0 or jsonb_typeof(p_result->'contacts') is distinct from 'array' or octet_length(p_result::text)>262144 then raise exception 'Invalid contact result';end if;
 perform public.icash_record_cost_observation('dealmachine',p_operation,'dealmachine:owners:'||p_operation,used,'provider_credits');
 insert into public.icash_owner_contacts(screening_id,account_id,operation_key,result) values(p_screening,p_account,p_operation,p_result);
 if used>(select contact_credit_cap from public.icash_discovery_configs where account_id=p_account) then
 update public.icash_discovery_configs set contacts_enabled=false where account_id=p_account;
 end if;
end $function$

CREATE OR REPLACE FUNCTION public.icash_save_filtered_discovery(p_account uuid, p_operation text, p_revision uuid, p_page integer, p_result jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare page public.icash_discovery_filter_pages;n integer;saved jsonb;
begin
 perform 1 from public.icash_operation_spend where operation_key=p_operation and account_id=p_account for update;
 if not found then raise exception 'Filter operation required';end if;
 select * into page from public.icash_discovery_filter_pages where operation_key=p_operation and account_id=p_account for update;
 if not found or page.revision<>p_revision or page.sequence<>p_page or page.plan is distinct from p_result->'filterPlan' then raise exception 'Filter receipt scope changed';end if;
 if page.state='complete' then
  select result into saved from public.icash_discovery_results where operation_key=p_operation and account_id=p_account;
  if saved is distinct from p_result then raise exception 'Filter result conflict';end if;
  return (select count(*)::integer from public.icash_discovery_filter_attribution where operation_key=p_operation and account_id=p_account);
 end if;
 if page.state<>'claimed' then raise exception 'Filter claim required';end if;
 n:=public.icash_save_discovery(p_account,p_operation,p_revision,p_page,p_result);
 insert into public.icash_discovery_filter_attribution(screening_id,account_id,operation_key)
 select s.id,s.account_id,p_operation from public.icash_screening_jobs s
 where s.account_id=p_account and s.event_key=p_operation||':'||(s.snapshot->>'propertyId') on conflict do nothing;
 update public.icash_discovery_filter_cursors set next_page=next_page+1,pages=pages+1,exhausted=not coalesce((p_result->>'hasNextPage')::boolean,false)
 where account_id=p_account and revision=p_revision and strategy=page.plan->>'strategy';
 update public.icash_discovery_filter_pages set state='complete',completed_at=now() where operation_key=p_operation;
 update public.icash_discovery_configs set exhausted=not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted)
 where account_id=p_account and revision=p_revision;
 return n;
end $function$

CREATE OR REPLACE FUNCTION public.icash_record_discovery_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ids text[];queued integer;duplicates integer;plan jsonb;
begin
 select * into strict c from public.icash_discovery_configs where account_id=new.account_id;
 select coalesce(array_agg(value->>'dm_property_id'),'{}') into ids from jsonb_array_elements(new.result->'rows');
 select count(*) into queued from public.icash_screening_jobs s where s.account_id=new.account_id
 and s.event_key in (select new.operation_key||':'||pid.property_id from unnest(ids) as pid(property_id));
 select count(*) into duplicates from unnest(ids) as pid(property_id)
 join public.icash_outbound_property_owners o on o.property_id=pid.property_id
 where not exists(select 1 from public.icash_screening_jobs s where s.account_id=new.account_id
  and s.event_key=new.operation_key||':'||pid.property_id);
 plan:=new.result->'filterPlan';
 insert into public.icash_discovery_inventory_receipts(operation_key,account_id,revision,zip,strategy,provider_page,per_page,property_ids,returned_properties,queued_properties,duplicate_properties,has_next_page,created_at)
 values(new.operation_key,new.account_id,c.revision,c.zip,coalesce(plan->>'strategy','baseline'),coalesce((plan->>'providerPage')::integer,c.next_page),c.per_page,ids,cardinality(ids),queued,duplicates,(new.result->>'hasNextPage')::boolean,new.created_at);
 return new;
end $function$
